sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = ['document'];
    var kpiValues = {
        'document': []
    };

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            try {
                gs.log("Raw property value: " + propertyValue);
                kpis = JSON.parse(propertyValue);
                gs.log("Parsed KPIs for " + propertyName + ": " + JSON.stringify(kpis));
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.log("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    function processKPI(kpis, kpiType) {
        if (Array.isArray(kpis)) {
            gs.log("Processing KPIs for " + kpiType + ": " + JSON.stringify(kpis));
            kpis.forEach(function (link) {
                kpiValues[kpiType].push({
                    'name':link.title || '',
                    'url': link.url || '',
                    'description':link.description || ''
                });

                gs.log("Processed KPI Link: " + JSON.stringify(kpiValues[kpiType][kpiValues[kpiType].length - 1]));
            });
        } else {
            gs.log("Invalid KPI format for " + kpiType + ": " + JSON.stringify(kpis));
        }
    }

    function getQueryCount(tableName, query) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addEncodedQuery(query);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.log("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    function getTotalCount(tableName) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.log("Error querying total count for table " + tableName + ": " + error.message);
            return 0;
        }
    }

    // Loop through KPI properties and process
    kpiProperties.forEach(function (property) {
        gs.log("Fetching KPIs for property: " + property);
        var kpis = fetchKPIs(property);
        processKPI(kpis, property);
    });

    return kpiValues;
}
